INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q707203', 'harihara-ii-1377-vijayanagara', 'Wikipedia summary (Harihara II)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q707203' AND "person_id" = 'harihara-ii-1377-vijayanagara');
UPDATE "people" SET "summary" = 'Mahinda V was King of Anuradhapura in the 11th century. He was the last king of the Anuradhapura Kingdom as well as from the House of Lambakanna II. In 993, he fled to Ruhuna, the southern part of the country, following a large scale mutiny by his army.' WHERE "id" = 'mahinda-v-1001-anuradhapura' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q6734027', 'mahinda-v-1001-anuradhapura', 'Wikipedia summary (Mahinda V)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q6734027' AND "person_id" = 'mahinda-v-1001-anuradhapura');
UPDATE "people" SET "summary" = 'Vira Narasimha Raya, also known as  Vira Narasimha or Vira Narasimha III, became the Emperor of Vijayanagara after the death of his predecessor Narasimha Raya II. He was the older half-brother of Krishnadevaraya.' WHERE "id" = 'viranarasimha-raya-1503-vijayanagara' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q1113900', 'viranarasimha-raya-1503-vijayanagara', 'Wikipedia summary (Viranarasimha Raya)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q1113900' AND "person_id" = 'viranarasimha-raya-1503-vijayanagara');
UPDATE "people" SET "summary" = 'Muhammad Shah III Lashkari, also known as Shamsuddin Muhammad Shah III, was the sultan of the Bahmani Sultanate from 1463 to 1482. During his reign, he successfully invaded Orissa, compelling its ruler Purushottam Deva to surrender. He also made his brother Hamvira Deva surrender by besieging Kondavidu fort.' WHERE "id" = 'muhammad-shah-bahmani-iii-1463-bahmani' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q4519937', 'muhammad-shah-bahmani-iii-1463-bahmani', 'Wikipedia summary (Muhammad Shah III Lashkari)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q4519937' AND "person_id" = 'muhammad-shah-bahmani-iii-1463-bahmani');
UPDATE "people" SET "summary" = 'Ibrahim Adil Shah II was the Adil Shahi sultan of the Sultanate of Bijapur from 1580 to 1627. Under his reign the sultanate had its greatest period as he extended its frontier as far south as Mysore. He was a skilful administrator, artist, poet and a generous patron of the arts.' WHERE "id" = 'ibrahim-adil-shah-ii-1580-bijapur' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q3631019', 'ibrahim-adil-shah-ii-1580-bijapur', 'Wikipedia summary (Ibrahim Adil Shah II)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q3631019' AND "person_id" = 'ibrahim-adil-shah-ii-1580-bijapur');
UPDATE "people" SET "summary" = 'Jalal-ud-Din Khalji, also known as Firuz al-Din Khalji, Jalaluddin Khilji or Firuz II was the Sultan of Delhi from 1290 until his death in 1296. He was the founder and first Sultan of the Khalji dynasty that ruled the Delhi Sultanate of India from 1290 to 1320.' WHERE "id" = 'jalal-ud-din-khalji-1290-delhi-sultanate' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q2691885', 'jalal-ud-din-khalji-1290-delhi-sultanate', 'Wikipedia summary (Jalal-ud-Din Khalji)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q2691885' AND "person_id" = 'jalal-ud-din-khalji-1290-delhi-sultanate');
UPDATE "people" SET "summary" = 'Lalitaditya alias Muktapida was a Karkota monarch of the Kashmir region in the Indian subcontinent. The 12th-century Kashmiri chronicler Kalhana characterizes Lalitaditya as a "world conqueror", crediting him with miraculous powers and extensive conquests across India and Central Asia.' WHERE "id" = 'lalitaditya-muktapida-724-karkota' AND "summary" IS NULL;
