UPDATE "people" SET "summary" = 'Ali Adil Shah II was the 8th Sultan of Bijapur. He succeeded to the throne of Bijapur through the efforts of the Prime Minister Khan Muhammad and the Queen, Badi Sahiba, sister of Qutb Shah of Golkonda on the death of Mohammed Adil Shah of Bijapur on 4 November 1656.' WHERE "id" = 'ali-adil-shah-ii-1656-bijapur' AND "summary" IS NULL;
