UPDATE "people" SET "summary" = 'Virupaksha Raya II was the Emperor of Vijayanagara from October 1465 until his death in 1485. from the Sangama dynasty.' WHERE "id" = 'virupaksha-raya-ii-1465-vijayanagara' AND "summary" IS NULL;
