UPDATE "people" SET "summary" = 'Abul Mujāhid Sikandar Shāh, commonly known as Sikandar Shah, was the second Sultan of Bengal and the Ilyas Shahi dynasty. He was the son of Shamsuddin Ilyas Shah. Sikandar Shah continued to project the imperial ambitions of his father. He defeated the Sultan of Delhi in 1359.' WHERE "id" = 'sikandar-shah-1358-bengal-sultanate' AND "summary" IS NULL;
