UPDATE "people" SET "summary" = 'Sriranga Deva Raya, also known as Sriranga I, was the second Emperor of Vijayanagara from the Aravidu Dynasty. He reigned from the fortress of Penukonda. Sriranga succeeded his father, Emperor Tirumala Deva Raya.' WHERE "id" = 'sriranga-i-1572-vijayanagara' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q1452348', 'sriranga-i-1572-vijayanagara', 'Wikipedia summary (Sriranga Deva Raya)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q1452348' AND "person_id" = 'sriranga-i-1572-vijayanagara');
UPDATE "people" SET "summary" = 'Deva Raya I was an Yadava Emperor of the Vijayanagara Empire. After Harihara II died, there was a dispute among his sons over succession, in which Deva Raya I eventually emerged victor. He was a very capable ruler noted for his military exploits and his support to irrigation works in his empire.' WHERE "id" = 'deva-raya-1406-vijayanagara' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q2336324', 'deva-raya-1406-vijayanagara', 'Wikipedia summary (Deva Raya I)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q2336324' AND "person_id" = 'deva-raya-1406-vijayanagara');
UPDATE "people" SET "summary" = 'Ibrahim Adil Shah I was sultan of the Indian Sultanate of Bijapur. He succeeded his elder brother, Mallu Adil Shah, through the machinations of the Afaqi faction at the court. He was the first Adil Shahi ruler to assume the royal title of Shah.' WHERE "id" = 'ibrahim-adil-shah-i-1535-bijapur' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q5984420', 'ibrahim-adil-shah-i-1535-bijapur', 'Wikipedia summary (Ibrahim Adil Shah I)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q5984420' AND "person_id" = 'ibrahim-adil-shah-i-1535-bijapur');
UPDATE "people" SET "summary" = 'Bahlul Khan Lodi was the chief of the Afghan Lodi tribe. He was the founder of the Lodi dynasty from the Delhi Sultanate, upon the abdication of the last claimant from the previous Sayyid dynasty. Bahlul became sultan of the dynasty on 19 April 1451.' WHERE "id" = 'bahlul-khan-lodi-1451-delhi-sultanate' AND "summary" IS NULL;
