UPDATE "people" SET "summary" = 'Rama Raya was a statesman of the Vijayanagara Empire, the son-in-law of Emperor Krishna Deva Raya and the progenitor of the Aravidu dynasty of Vijayanagara Empire, the fourth and last dynasty of the empire.' WHERE "id" = 'aliya-rama-raya-1542-vijayanagara' AND "summary" IS NULL;
