UPDATE "people" SET "summary" = 'Sultan Quli Qutb-ul-Mulk, more often though less correctly referred to in English as Quli Qutb Shah, was the founder of the Qutb Shahi dynasty, which ruled the Sultanate of Golconda in southern India from 1518 to 1687.' WHERE "id" = 'sultan-quli-1518-golconda' AND "summary" IS NULL;
