UPDATE "people" SET "summary" = 'Shihab-ud-Din Ahmad Shah I Bahmani, also known as Ahmad Shah Wali, was the Sultan of the Bahmani Sultanate from 1 October 1422 to 17 April 1436, and was a great patron of arts and culture.' WHERE "id" = 'ahmed-shah-wali-bahmani-1422-bahmani' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q3482078', 'ahmed-shah-wali-bahmani-1422-bahmani', 'Wikipedia summary (Ahmad Shah I Wali)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q3482078' AND "person_id" = 'ahmed-shah-wali-bahmani-1422-bahmani');
UPDATE "people" SET "summary" = 'Qutb ud-Din Aibak was a Turkic general of the Ghurid emperor Muhammad Ghori. He was in charge of the Ghurid territories in northern India, and after Muhammad Ghori''s assassination in 1206, he established his own independent rule in Lahore, laying the foundations for the Sultanate of Delhi.' WHERE "id" = 'qutb-ud-din-aibak-1206-delhi-sultanate' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q311151', 'qutb-ud-din-aibak-1206-delhi-sultanate', 'Wikipedia summary (Qutb ud-Din Aibak)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q311151' AND "person_id" = 'qutb-ud-din-aibak-1206-delhi-sultanate');
UPDATE "people" SET "summary" = 'Aram Shah was the second sultan of the Mamluk Sultanate. He briefly held the throne from Lahore after the unexpected death of Qutb ud-Din Aibak before being defeated and dethroned by Iltutmish who began ruling from Delhi.' WHERE "id" = 'aram-shah-1210-delhi-sultanate' AND "summary" IS NULL;
INSERT INTO "information_sources" ("source_id", "person_id", "note") SELECT 'wikipedia-ruler-Q2349158', 'aram-shah-1210-delhi-sultanate', 'Wikipedia summary (Aram Shah)' WHERE NOT EXISTS (SELECT 1 FROM "information_sources" WHERE "source_id" = 'wikipedia-ruler-Q2349158' AND "person_id" = 'aram-shah-1210-delhi-sultanate');
UPDATE "people" SET "summary" = 'Mu''izz al-Din Muhammad ibn Sam, also known as Muhammad of Ghor or Muhammad Ghori, was a ruler from the Ghurid dynasty based in the Ghur region of what is today central Afghanistan who ruled from 1173 to 1206. Muhammad and his elder brother Ghiyath al-Din Muhammad ruled in a dyarchy until the latter''s death in 1203.' WHERE "id" = 'muhammad-of-ghor-1203-ghurid' AND "summary" IS NULL;
