-- 2. Populate missing language_code on other_names
UPDATE "other_names" SET "language_code" = 'ta' WHERE "language_code" IS NULL AND "name_kind" = 'native' AND ("kingdom_id" IN ('chola', 'pandya', 'chera') OR "person_id" IN ('rajaraja-i', 'rajendra-i'));
UPDATE "other_names" SET "language_code" = 'te' WHERE "language_code" IS NULL AND "name_kind" = 'native' AND "kingdom_id" = 'vijayanagara';
UPDATE "other_names" SET "language_code" = 'kn' WHERE "language_code" IS NULL AND "name_kind" = 'native' AND ("kingdom_id" IN ('rashtrakuta', 'hoysala') OR "person_id" = 'krishnadevaraya');
UPDATE "other_names" SET "language_code" = 'hi' WHERE "language_code" IS NULL AND "name_kind" = 'native' AND ("kingdom_id" IN ('pala', 'pratihara') OR "person_id" IN ('dharmapala', 'mihira-bhoja'));
UPDATE "other_names" SET "language_code" = 'fa' WHERE "language_code" IS NULL AND "name_kind" = 'native' AND "kingdom_id" IN ('delhi-sultanate', 'bahmani');
UPDATE "other_names" SET "language_code" = 'en' WHERE "language_code" IS NULL AND "name_kind" = 'other';

-- 3. Deduplicate places (9 named place collisions + 152 site-Q* / monument-Q* pairs)
UPDATE "places" p SET "protected_place" = true, "start_year" = s."start_year", "map_properties" = s."map_properties" FROM "places" s WHERE p."id" = 'fatehpur-sikri' AND s."id" = 'site-Q179046';
UPDATE "places" p SET "protected_place" = true, "start_year" = s."start_year", "map_properties" = s."map_properties" FROM "places" s WHERE p."id" = 'gauda' AND s."id" = 'site-Q13058783';
UPDATE "places" p SET "start_year" = s."start_year", "map_properties" = s."map_properties" FROM "places" s WHERE p."id" = 'madurai' AND s."id" = 'site-Q1424358';
UPDATE "places" p SET "protected_place" = true, "map_properties" = COALESCE(p."map_properties", m."map_properties") FROM "places" m WHERE (p."id" = 'ellora' AND m."id" = 'monument-Q189616') OR (p."id" = 'hampi' AND m."id" = 'monument-Q26732') OR (p."id" = 'bateshwar' AND m."id" = 'monument-Q4868834') OR (p."id" = 'raigad-fort' AND m."id" = 'monument-Q3626515');
DELETE FROM "information_sources" WHERE "place_id" IN ('site-Q179046', 'monument-Q179046', 'site-Q13058783', 'monument-Q13058783', 'site-Q1424358', 'monument-Q189616', 'monument-Q26732', 'monument-Q4868834', 'monument-Q3626515');
DELETE FROM "places" WHERE "id" IN ('site-Q179046', 'monument-Q179046', 'site-Q13058783', 'monument-Q13058783', 'site-Q1424358', 'monument-Q189616', 'monument-Q26732', 'monument-Q4868834', 'monument-Q3626515');
UPDATE "places" s SET "protected_place" = true FROM "places" m WHERE s."id" LIKE 'site-Q%' AND m."id" = 'monument-' || substring(s."id" from 6);
DELETE FROM "information_sources" WHERE "place_id" IN (SELECT m."id" FROM "places" m JOIN "places" s ON m."id" = 'monument-' || substring(s."id" from 6) WHERE s."id" LIKE 'site-Q%');
DELETE FROM "places" m USING "places" s WHERE s."id" LIKE 'site-Q%' AND m."id" = 'monument-' || substring(s."id" from 6);
UPDATE "places" SET "region" = 'Indian subcontinent' WHERE "region" IS NULL;

-- 4. Repair 9 invalid PostGIS polygons in kingdom_borders and enforce ST_IsValid
UPDATE "kingdom_borders" SET "outline" = ST_Multi(ST_CollectionExtract(ST_MakeValid("outline"), 3)) WHERE NOT ST_IsValid("outline");
ALTER TABLE "kingdom_borders" DROP CONSTRAINT IF EXISTS "kingdom_borders_outline_valid_check";
ALTER TABLE "kingdom_borders" ADD CONSTRAINT "kingdom_borders_outline_valid_check" CHECK (ST_IsValid("outline"));
UPDATE "kingdom_borders" SET "from_year" = 844 WHERE "id" = 'chera-0';

