UPDATE "events" SET "summary" = 'Armed conflict recorded in 748 CE (Friday Battle). The exact battlefield coordinates are not recorded.' WHERE "id" = 'battle-friday-battle-748';
UPDATE "events" SET "summary" = 'Battle fought at Kanchi in 803 CE between rival southern dynasties. The exact battlefield coordinates are not recorded.' WHERE "id" = 'battle-battle-of-kanchi-803';
UPDATE "events" SET "summary" = 'Siege and battle at Uch (Ucha) in 1222 CE during campaigns in the Indus valley. The exact battlefield coordinates are not recorded.' WHERE "id" = 'battle-battle-of-ucha-1222';
UPDATE "events" SET "summary" = 'Battle fought near Mandavgad (Mandu) in 1437 CE between the Sultanates of Malwa and Mewar. The exact battlefield coordinates are not recorded.' WHERE "id" = 'battle-battle-of-mandavgad-1437';
