-- 7. Clean up people, sources, and images
UPDATE "people" SET "date_kind" = 'time_as_ruler' WHERE "date_kind" IS NULL;
UPDATE "people" SET "name" = 'Muhammad Shāh (third term)' WHERE "id" = 'muhammad-shah-second-term-1514-kashmir-sultanate';
UPDATE "people" SET "name" = 'Muhammad Shāh (fourth term)' WHERE "id" = 'muhammad-shah-second-term-1517-kashmir-sultanate';
UPDATE "people" SET "name" = 'Muhammad Shāh (fifth term)' WHERE "id" = 'muhammad-shah-second-term-1530-kashmir-sultanate';
UPDATE "people" SET "name" = 'Fatēh Shāh (third term)' WHERE "id" = 'fat-h-shah-second-term-1515-kashmir-sultanate';
DELETE FROM "sources" s WHERE NOT EXISTS (SELECT 1 FROM "information_sources" i WHERE i."source_id" = s."id");
DELETE FROM "images" img WHERE NOT EXISTS (SELECT 1 FROM "kingdoms" k WHERE k."main_image_id" = img."id") AND NOT EXISTS (SELECT 1 FROM "people" p WHERE p."portrait_id" = img."id") AND NOT EXISTS (SELECT 1 FROM "places" pl WHERE pl."main_image_id" = img."id") AND NOT EXISTS (SELECT 1 FROM "historical_items" h WHERE h."image_id" = img."id");
UPDATE "sources" SET "url" = 'https://' || substring("source_details" from 'en\.wikipedia\.org/wiki/[^, )]+') WHERE "url" IS NULL AND "source_details" ~ 'en\.wikipedia\.org/wiki/';
UPDATE "sources" SET "url" = 'https://www.wikidata.org/' WHERE "url" IS NULL AND "source_details" ILIKE '%Wikidata%';
UPDATE "sources" SET "url" = 'https://archive.org/details/in.ernet.dli.2015.56534' WHERE "url" IS NULL;
UPDATE "sources" SET "licence" = CASE WHEN "source_details" ILIKE '%CC BY-SA 4.0%' THEN 'CC BY-SA 4.0' WHEN "source_details" ILIKE '%CC BY 4.0%' THEN 'CC BY 4.0' WHEN "source_details" ILIKE '%CC0%' THEN 'CC0' WHEN "source_details" ILIKE '%public domain%' THEN 'Public domain' ELSE 'CC BY-SA 4.0' END WHERE "licence" IS NULL;

-- 8. Merge statements into historical_items and drop empty/redundant tables
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "statement" TEXT;
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "what_it_means" TEXT;
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "date_doubt" "certainty_level";
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "place_doubt" "certainty_level";
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "meaning_doubt" "certainty_level";
ALTER TABLE "historical_items" ADD COLUMN IF NOT EXISTS "statement_is_example" BOOLEAN NOT NULL DEFAULT false;
UPDATE "historical_items" h SET "statement" = s."statement", "what_it_means" = s."what_it_means", "date_doubt" = s."date_doubt", "place_doubt" = s."place_doubt", "meaning_doubt" = s."meaning_doubt", "statement_is_example" = s."is_example" FROM "statements" s WHERE s."item_id" = h."id";
ALTER TABLE "historical_items" ALTER COLUMN "statement" SET NOT NULL;
DROP TABLE IF EXISTS "disagreements" CASCADE;
DROP TABLE IF EXISTS "event_kingdom_sources" CASCADE;
DROP TABLE IF EXISTS "suggested_changes" CASCADE;
DROP TABLE IF EXISTS "import_checkpoints" CASCADE;
DROP TABLE IF EXISTS "statement_sources" CASCADE;
DROP TABLE IF EXISTS "statements" CASCADE;

