ALTER TABLE "information_sources" DROP CONSTRAINT IF EXISTS "information_sources_check";
ALTER TABLE "information_sources" DROP COLUMN IF EXISTS "capital_id";
ALTER TABLE "information_sources" ADD CONSTRAINT "information_sources_check" CHECK (num_nonnulls("kingdom_id", "person_id", "place_id", "event_id", "border_id", "route_id", "item_id") = 1);
ALTER TABLE "historical_items" DROP CONSTRAINT IF EXISTS "historical_items_check", DROP CONSTRAINT IF EXISTS "historical_items_check2";
