ALTER TABLE "places" DROP CONSTRAINT IF EXISTS "places_check", DROP CONSTRAINT IF EXISTS "places_check1", DROP CONSTRAINT IF EXISTS "places_check2";
ALTER TABLE "places" DROP COLUMN IF EXISTS "end_year", DROP COLUMN IF EXISTS "start_date_type", DROP COLUMN IF EXISTS "end_date_type", DROP COLUMN IF EXISTS "date_confidence", DROP COLUMN IF EXISTS "date_notes";
ALTER TABLE "kingdom_capitals" DROP CONSTRAINT IF EXISTS "kingdom_capitals_check", DROP CONSTRAINT IF EXISTS "kingdom_capitals_check1", DROP CONSTRAINT IF EXISTS "kingdom_capitals_check2";
ALTER TABLE "kingdom_capitals" DROP COLUMN IF EXISTS "from_year", DROP COLUMN IF EXISTS "to_year", DROP COLUMN IF EXISTS "start_date_type", DROP COLUMN IF EXISTS "end_date_type", DROP COLUMN IF EXISTS "date_confidence", DROP COLUMN IF EXISTS "date_notes";
ALTER TABLE "item_text_lines" DROP CONSTRAINT IF EXISTS "item_text_lines_check", DROP CONSTRAINT IF EXISTS "item_text_lines_check1";
ALTER TABLE "item_text_lines" DROP COLUMN IF EXISTS "original_words", DROP COLUMN IF EXISTS "words_in_latin_letters", DROP COLUMN IF EXISTS "box_left", DROP COLUMN IF EXISTS "box_top", DROP COLUMN IF EXISTS "box_width", DROP COLUMN IF EXISTS "box_height";
ALTER TABLE "kingdoms" DROP COLUMN IF EXISTS "date_notes";
